const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lakeSambhar = ee.Geometry.Polygon([
    [[74.9, 27.0], [75.1, 27.0], [75.1, 26.9], [74.9, 26.9], [74.9, 27.0]]
  ]);

  // 2. Data Acquisition - JRC Global Surface Water
  const jrc2018 = ee.Image('JRC/GSW1_3/YearlyHistory/2018');
  const jrc2019 = ee.Image('JRC/GSW1_3/YearlyHistory/2019');

  // Check if images exist
  try {
    const band2018 = jrc2018.bandNames().getInfo();
    const band2019 = jrc2019.bandNames().getInfo();
    console.log(`2018 bands: ${band2018.length}, 2019 bands: ${band2019.length}`);
  } catch (e) {
    console.log("Image access failed - trying alternative approach");
    print("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate water extent (water = classification == 2)
  const water2018 = jrc2018.eq(2).selfMask();
  const water2019 = jrc2019.eq(2).selfMask();

  // Count water pixels
  const count2018 = water2018.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: lakeSambhar,
    scale: 30,
    maxPixels: 1e9
  }).get('classification').getInfo();

  const count2019 = water2019.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: lakeSambhar,
    scale: 30,
    maxPixels: 1e9
  }).get('classification').getInfo();

  console.log(`2018 water pixels: ${count2018}`);
  console.log(`2019 water pixels: ${count2019}`);

  // 4. Validation & Final Answer
  if (count2018 === null || count2019 === null || isNaN(count2018) || isNaN(count2019)) {
    console.log("Calculation failed - null/NaN values");
    print("<answer>C3</answer>");
  } else if (count2018 === 0 || count2019 === 0) {
    console.log("No valid water pixels detected");
    print("<answer>C2</answer>");
  } else if (count2019 < count2018) {
    console.log(`Water extent decreased: ${count2019} < ${count2018}`);
    print("<answer>A</answer>");
  } else {
    console.log(`Water extent did not decrease: ${count2019} >= ${count2018}`);
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
